result:
        ids = [row.get("id") for row in rows if isinstance(row, dict)]
        calls.append({"args": terms, "exit": code, "hits": len(rows),
                      "ids": ids, "stderr": err.strip()[-300:]})
        for row in rows:
            rid = row.get("id")
            if rid and rid not in seen:
                seen.add(rid)
                hits.append(row)
    return {"calls": calls, "hits": hits}


